package android.graphics; public final class Insets { public static final Insets NONE=new Insets(0,0,0,0); public final int left,top,right,bottom; private Insets(int l,int t,int r,int b){left=l;top=t;right=r;bottom=b;} public static Insets of(int l,int t,int r,int b){return l==0&&t==0&&r==0&&b==0?NONE:new Insets(l,t,r,b);} public static Insets of(Rect r){return of(r.left,r.top,r.right,r.bottom);} public boolean equals(Object o){if(!(o instanceof Insets))return false;Insets i=(Insets)o;return left==i.left&&top==i.top&&right==i.right&&bottom==i.bottom;} public int hashCode(){return ((left*31+top)*31+right)*31+bottom;} }